"""Campaign design for "The Hundred": 8 acts x 5 chapters, enemies, bosses, story beats and side quests.

gen_campaign.py turns this into chapters/fights/enemies/droptables/equipment/story rows. Chapters 1-3 already exist
(hand-written rows above the GENERATED marker); their design here only adds the extra fights, side quests and the
darker rewrite of their beats (same beat ids).

Speakers: a hero/enemy id, or 'narrator' (Corvin's chronicle), 'corvin', 'malrec', or any id with a display name.
Fight counts (9-11) and side-quest counts (1-3) per chapter come from a seeded roll (seed 40) and are asserted.
"""

# Seeded rolls (random.Random(40): 40 x randint(9, 11), then 40 x randint(1, 3)); gen_campaign.py re-rolls and asserts.
FIGHTS_PER_CHAPTER = [10, 11, 11, 9, 9, 10, 11, 11, 11, 9, 9, 10, 10, 11, 10, 9, 11, 11, 9, 9,
                      11, 9, 11, 11, 10, 9, 9, 11, 10, 9, 10, 10, 9, 11, 11, 11, 9, 10, 9, 10]
SIDES_PER_CHAPTER = [3, 2, 1, 3, 1, 2, 1, 3, 2, 3, 2, 2, 1, 3, 1, 2, 2, 3, 1, 1,
                     3, 1, 3, 3, 1, 1, 2, 3, 2, 1, 1, 1, 2, 2, 1, 2, 3, 2, 3, 2]

SPEAKERS = {'narrator': 'Narrator', 'corvin': 'Corvin', 'malrec': 'Malrec the Pale', 'ysra': 'Warden Ysra',
            'ilvane': 'Archmage Ilvane', 'villager': 'Villager', 'journal': 'Chronicle'}


def E(key, name, role, tint, active=None, passive=None, art=None, scale=1.0):
    """Enemy. role: grunt|brute|striker|archer|caster|healer|swarm|boss. art = base enemy key whose sprites it reuses."""
    return dict(key=key, name=name, role=role, tint=tint, active=active, passive=passive, art=art, scale=scale)


def S(name, desc, targeting, cooldown, effects, count=1):
    return dict(name=name, desc=desc, targeting=targeting, cooldown=cooldown, effects=effects, count=count)


def PS(name, desc, trigger, effects, targeting='Self', threshold=0, chance=0, cooldown=0, once=False, count=1):
    return dict(name=name, desc=desc, trigger=trigger, effects=effects, targeting=targeting, threshold=threshold,
                chance=chance, cooldown=cooldown, once=once, count=count)


def Q(name, pre, lore, relic=None):
    """Side quest: pre = (speaker, line), lore = journal text shown after the first clear, relic = (name, slot) or None."""
    return dict(name=name, pre=pre, lore=lore, relic=relic)


def C(name, fights, foes, intro, beats, boss, boss_line, outro, sides, elites=()):
    """Chapter. fights = fight names (len = rolled count, boss last), foes = enemy keys used here,
    beats = [(speaker, line)] spread over the middle fights, boss = enemy key, sides = [Q]."""
    return dict(name=name, fights=fights, foes=foes, elites=list(elites), intro=intro, beats=beats, boss=boss,
                boss_line=boss_line, outro=outro, sides=sides)


